mapper.select:
select id, event_id as eventId, trace_id as traceId, request_id as requestId, level, logger_name as loggerName, thread_name as threadName, biz_module as bizModule, source_app as sourceApp, host_name as hostName, environment, message, message_digest as messageDigest, exception_class as exceptionClass, stack_trace as stackTrace, occurred_at as occurredAt from log_runtime_record
and level = #{level}
and logger_name like concat('%', #{loggerName}, '%')
and (message like concat('%', #{keyword}, '%') or message_digest like concat('%', #{keyword}, '%'))
and occurred_at >= #{startTime}
and occurred_at <= #{endTime}
order by occurred_at desc
